/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATOR_CHARS = '+#./;?&';
const RESERVED_CHARS = '=,!@|';

const NAME_RE = /^(?:%[0-9A-Fa-f]{2}|[A-Za-z0-9_])+(?:\.(?:%[0-9A-Fa-f]{2}|[A-Za-z0-9_])+)*$/;
const MODIFIER_DIGITS_RE = /^[1-9][0-9]{0,3}$/;

function parseVariableSpec(spec, openIndex) {
  if (spec === '') throw new UriTemplateError(`empty variable specification at ${openIndex}`, openIndex);

  let explode = false;
  let maxLength = null;
  let name;

  if (spec.endsWith('*')) {
    explode = true;
    name = spec.slice(0, -1);
  } else if (spec.includes(':')) {
    const idx = spec.indexOf(':');
    name = spec.slice(0, idx);
    const modifierStr = spec.slice(idx);
    const digits = modifierStr.slice(1);
    if (!MODIFIER_DIGITS_RE.test(digits)) {
      throw new UriTemplateError(`invalid prefix modifier '${modifierStr}' at ${openIndex}`, openIndex);
    }
    maxLength = Number(digits);
  } else {
    name = spec;
  }

  if (!NAME_RE.test(name)) {
    throw new UriTemplateError(`invalid variable name '${name}' at ${openIndex}`, openIndex);
  }

  return { name, explode, maxLength };
}

function parseExpressionContent(content, openIndex) {
  if (content === '') throw new UriTemplateError(`empty expression at ${openIndex}`, openIndex);

  const first = content[0];
  let operator;
  let rest;

  if (OPERATOR_CHARS.includes(first)) {
    operator = first;
    rest = content.slice(1);
  } else if (RESERVED_CHARS.includes(first)) {
    throw new UriTemplateError(`reserved operator '${first}' at ${openIndex}`, openIndex);
  } else {
    operator = '';
    rest = content;
  }

  const pieces = rest.split(',');
  const variables = pieces.map((piece) => parseVariableSpec(piece, openIndex));

  return { type: 'expression', operator, variables };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  if (template === '') return [];

  const result = [];
  let buffer = '';
  let i = 0;
  const len = template.length;

  while (i < len) {
    const c = template[i];
    if (c === '{') {
      const closeIdx = template.indexOf('}', i + 1);
      if (closeIdx === -1) {
        throw new UriTemplateError(`unterminated expression at ${i}`, i);
      }
      if (buffer !== '') {
        result.push({ type: 'literal', value: buffer });
        buffer = '';
      }
      const content = template.slice(i + 1, closeIdx);
      result.push(parseExpressionContent(content, i));
      i = closeIdx + 1;
    } else if (c === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    } else {
      buffer += c;
      i += 1;
    }
  }

  if (buffer !== '') result.push({ type: 'literal', value: buffer });

  return result;
}
"}

